:root{--dark:#0f172a;--primary:#2563eb;--cyan:#06b6d4;--bg:#f4f8ff;--muted:#64748b}
.auth-page{min-height:100vh;display:grid;place-items:center;padding:24px}
.logo{width:72px;height:72px;border-radius:24px;display:grid;place-items:center;margin:0 auto 12px;background:linear-gradient(135deg,var(--primary),var(--cyan));color:#fff;font-size:34px;box-shadow:0 18px 40px rgba(37,99,235,.3)}
.demo-box{background:#f8fafc;border:1px solid #e2e8f0;border-radius:18px;padding:14px;margin-top:18px}
.topbar{height:66px;background:rgba(255,255,255,.78);backdrop-filter:blur(16px);border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;padding:0 26px;position:sticky;top:0;z-index:5}
.brand{font-size:24px;font-weight:900}.brand span{color:var(--primary)}.topbar-right{display:flex;align-items:center}
.layout{display:flex}
.sidebar{width:260px;background:#0b1220;color:#fff;padding:22px 16px;position:sticky;top:66px;height:calc(100vh - 66px)}
.sidebar-title{color:#93c5fd;font-weight:900;letter-spacing:.12em;font-size:.8rem;margin:6px 12px 16px}.sidebar a{display:block;color:#cbd5e1;text-decoration:none;padding:12px 14px;border-radius:16px;margin:5px 0;font-weight:650}.sidebar a:hover{background:rgba(255,255,255,.11);color:#fff;transform:translateX(4px)}
.content{flex:1}.hero{color:white}.hero h1{margin:0 0 8px}
.stat-card,.soft-card,.table-card{background:rgba(255,255,255,.92);border:1px solid rgba(148,163,184,.2);border-radius:16px;padding:22px;box-shadow:0 8px 24px rgba(35,52,95,.07)}.stat-value{font-weight:900}.table-card{overflow:auto}
.chat-shell{background:white}.chat-header{color:#fff}.chat-box{overflow:auto}.msg{max-width:86%;padding:15px 17px;border-radius:22px;margin-bottom:16px;line-height:1.55}.msg.user{color:#fff;margin-left:auto;border-bottom-right-radius:6px}.msg.bot{background:#fff;border:1px solid #dbeafe;border-bottom-left-radius:6px}.quick-chip{display:inline-block;padding:9px 13px;border-radius:999px;background:#eff6ff;border:1px solid #bfdbfe;margin:4px;cursor:pointer;font-weight:650;color:#1d4ed8;font-size:.92rem}.quick-chip:hover{background:#dbeafe}
.qr-card{border:2px dashed #93c5fd;border-radius:16px;text-align:center;padding:26px}
@media(max-width:900px){.sidebar{width:100%;height:auto;position:static}.topbar{height:auto;display:block;padding:16px}.topbar-right{margin-top:10px}}

.chart-grid{display:grid;grid-template-columns:repeat(12,1fr);align-items:end;background:#f8fafc;border-radius:20px}
.chart-bar{background:linear-gradient(180deg,#2563eb,#06b6d4);border-radius:12px 12px 4px 4px;min-height:16px;position:relative}
.chart-bar span{position:absolute;bottom:-26px;left:50%;transform:translateX(-50%);font-size:.75rem;color:#64748b}
.timeline{border-left:3px solid #bfdbfe;margin-left:12px;padding-left:18px}
.timeline-item{background:#fff;border:1px solid #dbeafe;border-radius:18px;padding:14px;margin-bottom:12px}
.kpi-mini{display:flex;align-items:center}
.kpi-icon{display:grid;place-items:center;background:#eff6ff;color:#2563eb}
details summary{cursor:pointer}
.priority-alert{border:1px solid #fed7aa;border-radius:18px;padding:14px}

.report-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}
.report-card{background:#fff;border:1px solid #dbeafe;border-radius:16px;padding:22px;box-shadow:0 8px 24px rgba(35,52,95,.07)}
.report-card h3{margin-top:0}
.report-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.print-page{background:white;color:#111827;font-family:Inter!important;padding:28px;max-width:960px;margin:24px auto;border-radius:12px}
.print-header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #2563eb;padding-bottom:14px;margin-bottom:20px}
.print-title{font-size:28px;font-weight:800;color:#1d4ed8}
.print-section{margin:18px 0}
.print-table{margin-top:10px}
.print-table th,.print-table td{border:1px solid #cbd5e1;padding:9px;text-align:left;vertical-align:top}
.print-table th{background:#eff6ff}
.print-note{background:#f8fafc;border:1px solid #e2e8f0;padding:12px;border-radius:10px}
.no-print-actions{max-width:960px;margin:20px auto;display:flex;gap:10px}
.donut{width:190px;height:190px;border-radius:50%;display:grid;place-items:center;margin:auto;background:conic-gradient(#2563eb 0 45%, #06b6d4 45% 75%, #93c5fd 75% 100%)}
.donut-inner{width:110px;height:110px;border-radius:50%;background:white;display:grid;place-items:center;text-align:center;font-weight:900}
.metric-list{display:grid;gap:10px}
.metric-row{display:flex;justify-content:space-between;border-bottom:1px solid #e2e8f0;padding-bottom:8px}
@media print{
    body{background:white!important}
    .topbar,.sidebar,.no-print-actions,.btn{display:none!important}
    .layout{display:block}
    .content{padding:0}
    .print-page{box-shadow:none;margin:0;max-width:100%;border-radius:0}
}

.vetrix-login-page{
    min-height:100vh;
    display:grid;
    grid-template-columns:1.15fr .85fr;
    position:relative;
    overflow:hidden;
    background:
        radial-gradient(circle at 12% 18%, rgba(37,99,235,.22), transparent 32%),
        radial-gradient(circle at 80% 8%, rgba(6,182,212,.22), transparent 28%),
        linear-gradient(135deg,#eef6ff,#f8fafc 45%,#ecfeff);
}
.login-orb{
    position:absolute;
    border-radius:999px;
    filter:blur(2px);
    opacity:.55;
    animation:floatOrb 8s ease-in-out infinite;
}
.orb-one{width:160px;height:160px;background:#bfdbfe;left:5%;top:8%}
.orb-two{width:220px;height:220px;background:#ccfbf1;right:10%;bottom:9%;animation-delay:1.4s}
.orb-three{width:90px;height:90px;background:#fde68a;left:45%;bottom:18%;animation-delay:2.2s}
@keyframes floatOrb{
    0%,100%{transform:translateY(0)}
    50%{transform:translateY(-22px)}
}
.vetrix-showcase{
    position:relative;
    z-index:1;
    padding:58px;
    display:flex;
    flex-direction:column;
    justify-content:center;
}
.showcase-badge{
    width:max-content;
    padding:10px 15px;
    border-radius:999px;
    background:rgba(255,255,255,.75);
    border:1px solid rgba(148,163,184,.3);
    color:#1d4ed8;
    font-weight:800;
    margin-bottom:18px;
    box-shadow:0 8px 20px rgba(35,52,95,.05);
}
.vetrix-showcase h1{
    font-size:clamp(48px,7vw,92px);
    letter-spacing:-.07em;
    line-height:.9;
    margin:0;
    background:linear-gradient(135deg,#0f172a,#2563eb,#0891b2);
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
}
.vetrix-showcase p{
    font-size:19px;
    line-height:1.7;
    color:#475569;
    max-width:680px;
}
.showcase-features{
    display:grid;
    grid-template-columns:repeat(4,minmax(120px,1fr));
    gap:12px;
    max-width:720px;
    margin-top:22px;
}
.showcase-features div{
    background:rgba(255,255,255,.76);
    border:1px solid rgba(148,163,184,.22);
    padding:14px;
    border-radius:18px;
    font-weight:800;
    color:#1e293b;
    box-shadow:0 8px 20px rgba(35,52,95,.05);
}
.vetrix-login-panel{
    position:relative;
    z-index:1;
    display:grid;
    place-items:center;
    padding:34px;
}
.login-card-pro{
    width:min(470px,96vw);
    background:rgba(255,255,255,.86);
    backdrop-filter:blur(22px);
    border:1px solid rgba(148,163,184,.26);
    box-shadow:0 20px 50px rgba(35,52,95,.12);
    border-radius:34px;
    padding:36px;
}
.mobile-logo{
    width:64px;
    height:64px;
    border-radius:22px;
    display:grid;
    place-items:center;
    background:linear-gradient(135deg,#2563eb,#06b6d4);
    color:white;
    font-size:30px;
    box-shadow:0 16px 36px rgba(37,99,235,.28);
    margin-bottom:18px;
}
.login-card-pro h2{
    margin:0 0 6px;
    font-size:34px;
    letter-spacing:-.04em;
}
.login-label{
    display:block;
    font-weight:800;
    font-size:.9rem;
    color:#334155;
    margin:16px 0 7px;
}
.login-input{
    background:#f8fafc;
    border:1px solid #dbeafe;
}
.login-input:focus{
    outline:3px solid rgba(37,99,235,.14);
    border-color:#2563eb;
}
.login-btn{
    box-shadow:0 18px 36px rgba(37,99,235,.26);
}
.login-demo-box{
    margin-top:22px;
    border:1px solid #e2e8f0;
    background:#f8fafc;
    border-radius:22px;
    padding:16px;
}
.login-demo-box div{
    display:flex;
    justify-content:space-between;
    gap:12px;
    margin-top:8px;
    color:#64748b;
}
.login-demo-box code{
    color:#1d4ed8;
    font-weight:800;
}

.dog-stage{
    width:min(600px,90vw);
    height:330px;
    position:relative;
    margin-top:34px;
    border-radius:38px;
    background:
        radial-gradient(circle at 50% 75%, rgba(37,99,235,.15), transparent 34%),
        linear-gradient(180deg,rgba(255,255,255,.52),rgba(255,255,255,.25));
    border:1px solid rgba(148,163,184,.22);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.6),0 12px 32px rgba(35,52,95,.08);
    cursor:grab;
    overflow:hidden;
}
.rub-hint{
    position:absolute;
    top:30px;
    left:50%;
    transform:translateX(-50%);
    background:rgba(255,255,255,.9);
    border:1px solid #dbeafe;
    padding:9px 14px;
    border-radius:999px;
    color:#2563eb;
    font-weight:900;
    z-index:4;
}
.dog{
    position:absolute;
    width:260px;
    height:220px;
    left:50%;
    top:52%;
    transform:translate(-50%,-50%);
    transition:transform .18s ease;
}
.dog-shadow{
    position:absolute;
    width:260px;
    height:42px;
    border-radius:50%;
    left:50%;
    bottom:42px;
    transform:translateX(-50%);
    background:rgba(15,23,42,.14);
    filter:blur(5px);
}
.dog-body{
    position:absolute;
    width:180px;
    height:105px;
    left:42px;
    top:88px;
    background:linear-gradient(135deg,#f8fafc,#e2e8f0);
    border:5px solid #334155;
    border-radius:70px 80px 55px 60px;
    z-index:2;
}
.dog-spot{
    position:absolute;
    width:58px;
    height:48px;
    border-radius:50%;
    background:#94a3b8;
    left:76px;
    top:20px;
    opacity:.7;
}
.dog-leg{
    position:absolute;
    bottom:-30px;
    width:32px;
    height:52px;
    background:#f8fafc;
    border:5px solid #334155;
    border-radius:18px;
}
.leg-one{left:38px}
.leg-two{right:35px}
.dog-tail{
    position:absolute;
    width:80px;
    height:24px;
    right:4px;
    top:92px;
    background:#f8fafc;
    border:5px solid #334155;
    border-radius:30px;
    transform-origin:left center;
    z-index:1;
}
.dog-head{
    position:absolute;
    width:130px;
    height:118px;
    left:34px;
    top:18px;
    background:linear-gradient(135deg,#fff,#e2e8f0);
    border:5px solid #334155;
    border-radius:50px 50px 55px 55px;
    z-index:3;
    transition:transform .12s ease;
}
.dog-ear{
    position:absolute;
    width:42px;
    height:70px;
    background:#94a3b8;
    border:5px solid #334155;
    top:-18px;
    border-radius:30px 30px 35px 35px;
    z-index:-1;
}
.ear-left{left:-14px;transform:rotate(-22deg)}
.ear-right{right:-14px;transform:rotate(22deg)}
.dog-eye{
    position:absolute;
    width:14px;
    height:18px;
    background:#0f172a;
    border-radius:50%;
    top:42px;
    animation:blinkDog 4s infinite;
}
.eye-left{left:38px}
.eye-right{right:38px}
@keyframes blinkDog{
    0%,92%,100%{transform:scaleY(1)}
    95%{transform:scaleY(.12)}
}
.dog-snout{
    position:absolute;
    width:58px;
    height:42px;
    left:50%;
    top:58px;
    transform:translateX(-50%);
    background:#fff7ed;
    border:4px solid #334155;
    border-radius:16px;
}
.dog-nose{
    width:20px;
    height:14px;
    background:#0f172a;
    border-radius:50%;
    margin:7px auto 0;
}
.dog-mouth{
    width:22px;
    height:10px;
    border-bottom:4px solid #0f172a;
    border-radius:0 0 20px 20px;
    margin:1px auto;
}
.dog-heart{
    position:absolute;
    color:#ef4444;
    opacity:0;
    font-size:22px;
    z-index:5;
}
.heart-one{left:48px;top:14px}
.heart-two{left:122px;top:4px}
.heart-three{left:184px;top:35px}
.dog.is-happy .dog-tail{
    animation:tailWag .22s infinite alternate;
}
.dog.is-excited .dog-tail{
    animation:tailWag .13s infinite alternate;
}
.dog.is-excited .dog-heart{
    animation:heartPop 1.2s ease-in-out infinite;
}
.dog.is-excited .heart-two{animation-delay:.18s}
.dog.is-excited .heart-three{animation-delay:.33s}
.dog.is-happy .dog-body{
    animation:happyBounce .45s infinite alternate;
}
.dog-jump{
    animation:dogJump .5s ease;
}
@keyframes tailWag{
    from{transform:rotate(-18deg)}
    to{transform:rotate(30deg)}
}
@keyframes happyBounce{
    from{transform:translateY(0)}
    to{transform:translateY(-4px)}
}
@keyframes dogJump{
    0%,100%{transform:translate(-50%,-50%)}
    45%{transform:translate(-50%,-68%) rotate(-2deg)}
}
@keyframes heartPop{
    0%{opacity:0;transform:translateY(10px) scale(.6)}
    40%{opacity:1}
    100%{opacity:0;transform:translateY(-38px) scale(1.2)}
}
@media(max-width:980px){
    .vetrix-login-page{grid-template-columns:1fr}
    .vetrix-showcase{padding:32px 24px 0}
    .vetrix-login-panel{padding:24px}
    .showcase-features{grid-template-columns:repeat(2,1fr)}
    .dog-stage{height:260px}
}

.compact-dog-stage{
    height:280px;
}

.hero-with-animation{
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:24px;
    overflow:hidden;
    position:relative;
    min-height:210px;
}
.hero-text{
    position:relative;
    z-index:2;
}
.walk-scene{
    position:relative;
    width:min(420px,38vw);
    height:150px;
    flex:0 0 auto;
    overflow:hidden;
    border-radius:16px;
    background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,.05));
    border:1px solid rgba(255,255,255,.18);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.18);
}
.walking-ground{
    position:absolute;
    left:0;
    right:0;
    bottom:27px;
    height:5px;
    border-radius:999px;
    background:rgba(255,255,255,.5);
}
.walking-ground::before,
.walking-ground::after{
    content:"";
    position:absolute;
    bottom:0;
    width:80px;
    height:5px;
    border-radius:999px;
    background:rgba(255,255,255,.42);
    animation:groundMove 2.8s linear infinite;
}
.walking-ground::before{left:20px}
.walking-ground::after{left:210px;animation-delay:1.25s}
@keyframes groundMove{
    from{transform:translateX(230px)}
    to{transform:translateX(-330px)}
}
.walking-pair{
    position:absolute;
    bottom:31px;
    left:-190px;
    width:190px;
    height:105px;
    animation:walkPairAcross 9.5s linear infinite;
}
@keyframes walkPairAcross{
    0%{transform:translateX(-40px)}
    100%{transform:translateX(620px)}
}

.owner-svg{
    position:absolute;
    left:10px;
    bottom:0;
    width:70px;
    height:105px;
    animation:ownerBounce .45s ease-in-out infinite alternate;
}
@keyframes ownerBounce{
    from{transform:translateY(0)}
    to{transform:translateY(-4px)}
}
.owner-head{
    position:absolute;
    top:4px;
    left:25px;
    width:26px;
    height:26px;
    border-radius:50%;
    background:#fde68a;
    border:3px solid rgba(15,23,42,.75);
    z-index:3;
}
.owner-hair{
    position:absolute;
    top:0;
    left:21px;
    width:30px;
    height:25px;
    background:#3b2f2f;
    border-radius:18px 18px 8px 8px;
    z-index:2;
}
.owner-body{
    position:absolute;
    top:34px;
    left:24px;
    width:30px;
    height:42px;
    border-radius:14px 14px 10px 10px;
    background:#f472b6;
    border:3px solid rgba(15,23,42,.72);
    z-index:2;
}
.owner-arm{
    position:absolute;
    top:42px;
    width:10px;
    height:38px;
    border-radius:999px;
    background:#fde68a;
    border:3px solid rgba(15,23,42,.72);
    transform-origin:top center;
}
.arm-front{
    left:48px;
    transform:rotate(-28deg);
    animation:armSwingFront .7s ease-in-out infinite alternate;
}
.arm-back{
    left:17px;
    transform:rotate(25deg);
    animation:armSwingBack .7s ease-in-out infinite alternate;
}
@keyframes armSwingFront{
    from{transform:rotate(-34deg)}
    to{transform:rotate(22deg)}
}
@keyframes armSwingBack{
    from{transform:rotate(28deg)}
    to{transform:rotate(-20deg)}
}
.owner-leg{
    position:absolute;
    top:72px;
    width:11px;
    height:35px;
    border-radius:999px;
    background:#1e293b;
    transform-origin:top center;
}
.leg-front{
    left:42px;
    animation:legSwingFront .55s ease-in-out infinite alternate;
}
.leg-back{
    left:24px;
    animation:legSwingBack .55s ease-in-out infinite alternate;
}
@keyframes legSwingFront{
    from{transform:rotate(24deg)}
    to{transform:rotate(-28deg)}
}
@keyframes legSwingBack{
    from{transform:rotate(-24deg)}
    to{transform:rotate(28deg)}
}

.leash{
    position:absolute;
    left:63px;
    bottom:58px;
    width:68px;
    height:2px;
    background:rgba(255,255,255,.9);
    transform:rotate(13deg);
    transform-origin:left center;
    box-shadow:0 0 0 1px rgba(15,23,42,.18);
    animation:leashSway .65s ease-in-out infinite alternate;
}
@keyframes leashSway{
    from{transform:rotate(9deg)}
    to{transform:rotate(18deg)}
}

.mini-dog{
    position:absolute;
    right:12px;
    bottom:2px;
    width:78px;
    height:58px;
    animation:dogTrotting .34s ease-in-out infinite alternate;
}
@keyframes dogTrotting{
    from{transform:translateY(0)}
    to{transform:translateY(-3px)}
}
.mini-dog-body{
    position:absolute;
    left:10px;
    top:24px;
    width:54px;
    height:27px;
    border-radius:20px;
    background:#fff7ed;
    border:3px solid rgba(15,23,42,.75);
}
.mini-dog-head{
    position:absolute;
    left:50px;
    top:12px;
    width:28px;
    height:28px;
    border-radius:50% 50% 45% 45%;
    background:#fff7ed;
    border:3px solid rgba(15,23,42,.75);
}
.mini-dog-ear{
    position:absolute;
    left:48px;
    top:10px;
    width:14px;
    height:20px;
    border-radius:12px;
    background:#92400e;
    border:3px solid rgba(15,23,42,.75);
    transform:rotate(22deg);
    animation:earFlop .45s ease-in-out infinite alternate;
}
@keyframes earFlop{
    from{transform:rotate(14deg)}
    to{transform:rotate(35deg)}
}
.mini-dog-tail{
    position:absolute;
    left:0;
    top:25px;
    width:28px;
    height:9px;
    border-radius:999px;
    background:#fff7ed;
    border:3px solid rgba(15,23,42,.75);
    transform-origin:right center;
    animation:miniTailWag .18s infinite alternate;
}
@keyframes miniTailWag{
    from{transform:rotate(-22deg)}
    to{transform:rotate(28deg)}
}
.mini-dog-leg{
    position:absolute;
    top:47px;
    width:8px;
    height:17px;
    border-radius:999px;
    background:#1e293b;
    transform-origin:top center;
}
.dleg-one{
    left:25px;
    animation:dogLegOne .35s ease-in-out infinite alternate;
}
.dleg-two{
    left:51px;
    animation:dogLegTwo .35s ease-in-out infinite alternate;
}
@keyframes dogLegOne{
    from{transform:rotate(24deg)}
    to{transform:rotate(-24deg)}
}
@keyframes dogLegTwo{
    from{transform:rotate(-24deg)}
    to{transform:rotate(24deg)}
}
@media(max-width:900px){
    .hero-with-animation{
        display:block;
    }
    .walk-scene{
        width:100%;
        margin-top:18px;
    }
}

body:has(.admin-os-sidebar){
    --admin-radius:12px;
    --admin-shadow:0 8px 22px rgba(15,23,42,.055);
    --admin-shadow-hover:0 12px 28px rgba(15,23,42,.075);
}

body:has(.admin-os-sidebar) .hero,
body:has(.admin-os-sidebar) .admin-hero-banner,
body:has(.admin-os-sidebar) .client-hero-banner{
