.calendar-status-pill{
    display:inline-flex;
    align-items:center;
    gap:8px;
    border:1px solid #bfdbfe;
    background:rgba(255,255,255,.9);
    color:#334155;
    border-radius:999px;
    padding:10px 15px;
    font-weight:900;
    box-shadow:0 6px 18px rgba(35,52,95,.05);
}
.calendar-status-pill b{
    display:inline-grid;
