.modern-calendar{
    display:grid;
    grid-template-columns:repeat(7, minmax(145px, 1fr));
    background:rgba(255,255,255,.92);
    border:1px solid rgba(148,163,184,.22);
    border-radius:30px;
    overflow:auto;
    box-shadow:0 20px 48px rgba(15,23,42,.08);
}
.calendar-weekday{
    min-width:145px;
}
.modern-calendar-day{
    min-width:145px;
    min-height:150px;
    padding:10px;
    background:#fff;
    border-right:1px solid #e2e8f0;
    border-bottom:1px solid #e2e8f0;
    position:relative;
}
.modern-calendar-day:nth-child(7n){border-right:none}
.modern-calendar-day.muted{background:linear-gradient(135deg,#f8fafc,#f1f5f9)}
.modern-calendar-day.today{background:linear-gradient(135deg,#eff6ff,#ffffff)}
.modern-calendar-date{
    display:flex;
    justify-content:flex-end;
    align-items:center;
    gap:8px;
    margin-bottom:8px;
    color:#0f172a;
}
.modern-calendar-date span{
    display:grid;
    place-items:center;
    min-width:30px;
    height:30px;
    border-radius:999px;
    font-weight:800;
    font-size:1rem;
}
.modern-calendar-day.today .modern-calendar-date span{
    background:#2563eb;
    color:#fff;
}
.modern-calendar-date small{
    color:#2563eb;
    font-weight:900;
    font-size:.72rem;
}
.modern-calendar-events{
    display:flex;
    flex-direction:column;
    gap:6px;
}
.calendar-event{
    background:#fff;
    min-height:28px;
    cursor:pointer;
    transition:.18s ease;
    overflow:hidden;
}
.calendar-event:hover{
    transform:translateY(-1px);
    box-shadow:0 10px 22px rgba(15,23,42,.12);
}
.calendar-event span{line-height:1}
.calendar-event strong{font-weight:800;white-space:nowrap}
.calendar-event em{
    font-style:normal;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}
.calendar-event-pending{color:#d97706;background:#fffbeb}
.calendar-event-approved{color:#059669;background:#ecfdf5}
.calendar-event-completed{color:#2563eb;background:#eff6ff}
.calendar-event-cancelled{color:#e11d48;background:#fff1f2}
