    min-width:62px;
    display:grid;
    place-items:center;
    border-radius:22px;
    background:#eff6ff;
    font-size:28px;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.8);
}
.role-action-content{
    display:flex;
    flex-direction:column;
    gap:8px;
}
.role-action-content strong{
    font-size:1.18rem;
    font-weight:800;
    letter-spacing:-.03em;
    color:#0f172a;
}
.role-action-content small{
    max-width:620px;
    font-size:.96rem;
    line-height:1.55;
    color:#64748b;
}
.role-action-arrow{
    align-self:center;
    justify-self:end;
    padding:10px 14px;
    border-radius:999px;
    background:#eef6ff;
    color:#2563eb;
    font-weight:800;
    font-size:.88rem;
    white-space:nowrap;
}
@media(max-width:1000px){
    .role-action-grid{grid-template-columns:1fr;}
}
@media(max-width:640px){
    .role-action-card{grid-template-columns:1fr;align-items:start;padding:22px;min-height:auto;}
    .role-action-arrow{justify-self:start;}
}

.pos-product-form{display:grid;gap:12px;}
.pos-inline-edit{display:grid;grid-template-columns:minmax(90px,1fr) minmax(70px,.8fr) auto;gap:8px;align-items:center;min-width:260px;}
.pos-product-table td{vertical-align:middle;}
.pos-cashier-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(340px,.8fr);gap:26px;align-items:start;}
.pos-toolbar{display:grid;grid-template-columns:1fr 220px;gap:12px;}
.pos-product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-height:680px;overflow:auto;padding:4px 4px 12px;}
.pos-product-card{border:1px solid rgba(219,234,254,.95);background:rgba(255,255,255,.97);border-radius:16px;text-align:left;display:flex;flex-direction:column;box-shadow:0 18px 42px rgba(15,23,42,.06);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;color:#0f172a;}
.pos-product-card:hover:not(.is-disabled){transform:translateY(-3px);box-shadow:0 24px 52px rgba(15,23,42,.1);border-color:#bfdbfe;}
.pos-product-card.is-disabled{opacity:.55;cursor:not-allowed;filter:grayscale(.2);}
.pos-product-icon{width:48px;height:48px;border-radius:18px;background:#eff6ff;display:grid;place-items:center;font-size:23px;margin-bottom:2px;}
.pos-product-name{font-weight:900;font-size:1.02rem;line-height:1.2;color:#1e293b;}
.pos-product-meta{font-size:.86rem;color:#64748b;line-height:1.35;}
.pos-product-card strong{font-size:1.35rem;letter-spacing:-.04em;}
.pos-product-card small{color:#2563eb;font-weight:800;}
.pos-cart-panel{position:sticky;top:96px;}
.pos-cart-items{display:grid;gap:10px;margin:12px 0 16px;max-height:320px;overflow:auto;padding-right:4px;}
.pos-cart-item{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:12px;border:1px solid rgba(226,232,240,.9);border-radius:18px;background:#f8fafc;}
.pos-cart-item b,.pos-cart-item small{display:block;}
.pos-cart-item small{color:#64748b;font-size:.82rem;margin-top:2px;}
.pos-qty-controls{display:inline-flex;align-items:center;gap:8px;background:white;border:1px solid #e2e8f0;border-radius:999px;padding:4px 8px;}
.pos-qty-controls button{border:0;background:#eff6ff;color:#1d4ed8;border-radius:999px;width:24px;height:24px;font-weight:900;line-height:1;}
.pos-cart-total{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e2e8f0;border-bottom:1px solid #e2e8f0;padding:16px 0;margin:10px 0 14px;font-size:1.1rem;}
.pos-cart-total strong{font-size:1.8rem;letter-spacing:-.05em;color:#0f172a;}
.pos-change-row{display:flex;justify-content:space-between;color:#475569;background:#f8fafc;border-radius:16px;padding:10px 12px;margin-bottom:12px;}
@media(max-width:1200px){.pos-cashier-layout{grid-template-columns:1fr}.pos-cart-panel{position:static}.pos-product-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:680px){.pos-toolbar{grid-template-columns:1fr}.pos-product-grid{grid-template-columns:1fr}.pos-inline-edit{grid-template-columns:1fr}.pos-cart-item{grid-template-columns:1fr}.pos-qty-controls{justify-content:center;width:max-content;}}

:root{
    --ai-blue:#2368f3;
    --ai-blue-dark:#0b3ea8;
    --ai-blue-soft:#e8f1ff;
    --ai-ink:#14213d;
    --ai-muted:#667085;
    --ai-line:#d9e7ff;
    --ai-surface:rgba(255,255,255,.88);
    --ai-surface-strong:#fff;
    --ai-cyan:#2ec7d3;
    --ai-green:#28b487;
    --ai-amber:#f5b84b;
}
body{
    letter-spacing:0;
}

.layout{
    align-items:stretch;
}

.content{
    position:relative;
}

.app-topbar{
    border-bottom:1px solid rgba(217,231,255,.88);
}

.brand-link{
    text-decoration:none;
    display:inline-flex;
    align-items:center;
    gap:10px;
    letter-spacing:0;
}

.brand-mark{
    width:42px;
    height:42px;
    border-radius:15px;
    display:inline-grid;
    place-items:center;
    background:linear-gradient(135deg,var(--ai-blue),var(--ai-cyan));
    color:#fff;
    box-shadow:0 14px 26px rgba(35,104,243,.24);
}

.topbar-right{
    gap:12px;
}

.user-chip{
    padding:10px 14px;
    border:1px solid rgba(217,231,255,.95);
    border-radius:999px;
    background:rgba(255,255,255,.72);
    color:#344054;
    font-weight:700;
}

.quick-ai-top,
.logout-btn,
.btn.rounded-pill,
.diagnosis-filter-pill,
.reference-expand-pill{
    border-radius:999px !important;
}

.quick-ai-top{
    border:0;
    background:linear-gradient(135deg,var(--ai-blue),var(--ai-cyan)) !important;
    color:#fff !important;
    box-shadow:0 14px 24px rgba(35,104,243,.24);
    font-weight:800;
}

.notif-drawn-bell{
    border-color:rgba(217,231,255,.95) !important;
    border-radius:15px !important;
    background:rgba(255,255,255,.86) !important;
    color:var(--ai-blue) !important;
    box-shadow:0 12px 24px rgba(20,33,61,.06) !important;
}

.app-sidebar{
    overflow:auto;
    border-right:1px solid rgba(255,255,255,.14);
}

.sidebar-profile{
    padding:14px;
    border:1px solid rgba(255,255,255,.18);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.16);
}

.sidebar-logo{
    background:rgba(255,255,255,.96);
    color:var(--ai-blue);
    box-shadow:0 12px 28px rgba(4,22,62,.2);
}

.app-sidebar .sidebar-title{
    color:#b9dcff;
    letter-spacing:.08em;
}

.app-sidebar a{
    position:relative;
    gap:12px;
    min-height:44px;
    color:#dbeafe;
    font-weight:700;
    letter-spacing:0;
}

.app-sidebar a::before{
    content:"";
    width:9px;
    height:9px;
    border-radius:999px;
    background:rgba(190,224,255,.58);
    box-shadow:0 0 0 4px rgba(255,255,255,.05);
}

.app-sidebar a:hover,
.app-sidebar a.active{
    background:rgba(255,255,255,.16);
    border-color:rgba(255,255,255,.18);
    color:#fff;
    transform:translateX(2px);
}

.app-sidebar a.active::before{
    background:#fff;
}

.hero,
.hero.hero-with-animation,
.client-hero-banner{
    position:relative;
    overflow:hidden;
    border-radius:34px;
    padding:34px;
    border:1px solid rgba(255,255,255,.52);
    background:
        linear-gradient(135deg,#0a4ec8 0%,#2368f3 52%,#2ec7d3 100%) !important;
    box-shadow:0 28px 70px rgba(35,104,243,.26);
}

.hero::before,
.hero.hero-with-animation::before{
    content:"";
    position:absolute;
    inset:18px 18px auto auto;
    width:280px;
    height:156px;
    border-radius:16px;
    background:
        linear-gradient(90deg,rgba(255,255,255,.24),rgba(255,255,255,.08)),
        repeating-linear-gradient(90deg,rgba(255,255,255,.34) 0 8px,transparent 8px 22px);
    border:1px solid rgba(255,255,255,.32);
    opacity:.65;
    pointer-events:none;
}

.hero::after,
.hero.hero-with-animation::after{
    content:"";
    position:absolute;
    right:58px;
    bottom:28px;
    width:118px;
    height:118px;
    border-radius:32px;
    background:
        linear-gradient(180deg,rgba(255,255,255,.95),rgba(232,241,255,.82));
    box-shadow:
        -122px -22px 0 -30px rgba(255,255,255,.58),
        0 20px 42px rgba(4,22,62,.18);
    opacity:.78;
    pointer-events:none;
}

.hero h1,
.hero.hero-with-animation h1,
.client-hero-banner h1{
    max-width:780px;
    font-size:42px;
    line-height:1.08;
    letter-spacing:0;
    font-weight:800;
}

.hero p,
.hero.hero-with-animation p,
.client-hero-banner p{
    max-width:700px;
    color:rgba(255,255,255,.86);
    font-weight:550;
}

.stat-card,
.soft-card,
.table-card,
.report-card,
.chart-card,
.analytics-card,
.dashboard-metric-card,
.role-action-card,
.quick-action-card,
.dashboard-list-card,
.appointment-request-card,
.friendly-appointment-card,
.admin-appointment-card,
.qr-card,
.empty-state{
    border:1px solid rgba(217,231,255,.9);
    background:var(--ai-surface);
    box-shadow:0 20px 52px rgba(20,33,61,.08);
    backdrop-filter:blur(18px);
}

.stat-card,
.soft-card,
.table-card,
.report-card,
.chart-card,
.analytics-card,
.appointment-request-card,
.friendly-appointment-card,
.admin-appointment-card,
.qr-card{
    border-radius:16px;
}

.stat-card:hover,
.soft-card:hover,
.chart-card:hover,
.dashboard-metric-card:hover,
.role-action-card:hover,
.quick-action-card:hover{
    border-color:#b7d3ff;
    box-shadow:0 28px 64px rgba(20,33,61,.11);
}

.stat-value,
.dashboard-metric-value,
.pos-cart-total strong{
    color:#102a56;
    letter-spacing:0;
}

.kpi-icon,
.dashboard-metric-icon,
.role-action-icon,
.pos-product-icon{
    background:linear-gradient(135deg,#eaf3ff,#f5fbff);
    color:var(--ai-blue);
    border:1px solid rgba(190,215,255,.9);
}

.dashboard-metric-grid,
.analytics-grid,
.role-action-grid,
.report-grid{
    gap:22px;
}

.dashboard-metric-card{
    padding:26px;
    border-radius:16px;
    background:
        linear-gradient(150deg,rgba(255,255,255,.98),rgba(239,247,255,.86));
}

.dashboard-metric-card:nth-child(2) .dashboard-metric-icon,
