.dashboard-metric-card:nth-child(4) .dashboard-metric-icon,
.stat-card:nth-child(4) .kpi-icon{color:var(--ai-amber);background:#fff8e6;}

.chart-card h3,
.soft-card h3,
.report-card h3,
.section-head h3{
    color:#102a56;
    font-weight:900;
    letter-spacing:0;
}

.text-muted,
.dashboard-metric-label,
.role-action-content small,
.pos-product-meta{
    color:var(--ai-muted) !important;
}

.table{
