    place-items:center;
    border-radius:16px;
    background:linear-gradient(135deg,#00d2ff,#2563eb);
    color:#06111f;
    font-weight:800;
    box-shadow:0 0 34px rgba(0,210,255,.36);
}

.ai-brand b,
.ai-side-user b{
    display:block;
    line-height:1;
}

.ai-brand small,
.ai-side-user small{
    display:block;
    margin-top:5px;
    color:#8a99ad;
    font-size:.78rem;
}

.ai-nav{
    display:grid;
    gap:8px;
}

.ai-nav a{
    display:flex;
    align-items:center;
    gap:12px;
    min-height:46px;
    padding:0 14px;
    border-radius:16px;
    color:#8a99ad;
    text-decoration:none;
    border:1px solid transparent;
    transition:background .2s ease,color .2s ease,border-color .2s ease,box-shadow .2s ease,transform .2s ease;
}

.ai-nav a span{
    width:34px;
    color:#4c5b70;
    font-size:.76rem;
    font-weight:800;
}

.ai-nav a:hover,
.ai-nav a.active{
    color:#fff;
    background:rgba(0,210,255,.08);
    border-color:#232d3f;
    box-shadow:0 0 28px rgba(0,210,255,.11);
    transform:translateX(2px);
}

.ai-nav a.active span{
    color:#00d2ff;
}

.ai-side-user{
    margin-top:auto;
    display:grid;
    grid-template-columns:44px 1fr;
    gap:12px;
    align-items:center;
    padding:14px;
    border-radius:16px;
    border:1px solid #232d3f;
    background:rgba(255,255,255,.03);
}

.ai-user-avatar{
    width:44px;
    height:44px;
    display:grid;
    place-items:center;
    border-radius:14px;
    background:#161b26;
    color:#00d2ff;
    font-weight:800;
}

.ai-side-user a{
    grid-column:1 / -1;
    display:block;
    padding:10px;
    border-radius:12px;
    text-align:center;
    color:#fff;
    text-decoration:none;
    background:linear-gradient(135deg,rgba(0,210,255,.18),rgba(37,99,235,.2));
    border:1px solid rgba(0,210,255,.22);
}

.ai-main{
    height:100vh;
    overflow:auto;
    padding:30px;
}

.ai-top{
    display:flex;
    justify-content:space-between;
    gap:24px;
    align-items:flex-start;
    margin-bottom:24px;
}

.ai-eyebrow{
    display:inline-flex;
    align-items:center;
    gap:8px;
    margin-bottom:10px;
    color:#00d2ff;
    font-size:.78rem;
    font-weight:900;
    letter-spacing:.08em;
    text-transform:uppercase;
}

.ai-eyebrow::before{
    content:"";
    width:7px;
    height:7px;
    border-radius:999px;
    background:#00d2ff;
    box-shadow:0 0 18px #00d2ff;
}

.ai-top h1{
    margin:0;
    max-width:780px;
    font-size:clamp(34px,4vw,58px);
    line-height:1.02;
    letter-spacing:0;
    font-weight:800;
}

.ai-top p{
    margin:14px 0 0;
    max-width:760px;
    color:#8a99ad;
    font-size:1rem;
    line-height:1.7;
}

.ai-top-actions{
    display:flex;
    gap:10px;
    align-items:center;
    flex-wrap:wrap;
}

.ai-top-actions a,
.ai-top-actions button,
.ai-placeholder a,
.ai-chat-panel button{
    border:0;
    border-radius:16px;
    padding:12px 16px;
    color:#06111f;
    background:linear-gradient(135deg,#00d2ff,#2f7df7);
    text-decoration:none;
    font-weight:900;
    box-shadow:0 18px 42px rgba(0,210,255,.18);
    transition:opacity .2s ease,transform .2s ease,box-shadow .2s ease;
}

.ai-top-actions a{
    color:#fff;
    background:rgba(255,255,255,.06);
    border:1px solid #232d3f;
    box-shadow:none;
}

.ai-top-actions a.ai-primary-action{
    color:#06111f;
    background:linear-gradient(135deg,#00d2ff,#2f7df7);
    border:0;
    box-shadow:0 18px 42px rgba(0,210,255,.18);
}

.ai-top-actions a:hover,
.ai-top-actions button:hover,
.ai-placeholder a:hover,
.ai-chat-panel button:hover{
    opacity:.9;
    transform:translateY(-2px);
}

.ai-kpis{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:16px;
    margin-bottom:16px;
}

.ai-kpi-card,
.ai-card,
.ai-insights,
.ai-workspace{
    border-radius:16px;
    border:1px solid #232d3f;
    background:linear-gradient(180deg,rgba(22,27,38,.94),rgba(15,20,31,.94));
    box-shadow:0 22px 60px rgba(0,0,0,.22);
}

.ai-kpi-card{
    min-height:188px;
    padding:18px;
    transition:transform .2s ease,box-shadow .2s ease,border-color .2s ease;
}

.ai-kpi-card:hover,
.ai-card:hover,
.ai-insights:hover,
.ai-workspace:hover{
    transform:translateY(-2px);
    border-color:rgba(0,210,255,.42);
    box-shadow:0 24px 70px rgba(0,210,255,.08),0 22px 60px rgba(0,0,0,.26);
}

.ai-card-head,
.ai-section-head{
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:16px;
}

.ai-card-head span{
    color:#8a99ad;
    font-weight:800;
}

.ai-card-head b,
.ai-live-dot{
    padding:6px 10px;
    border-radius:999px;
    color:#00d2ff;
    background:rgba(0,210,255,.1);
    border:1px solid rgba(0,210,255,.24);
    font-size:.78rem;
}

.ai-kpi-card strong{
    display:block;
    margin-top:20px;
    color:#fff;
    font-size:40px;
    line-height:1;
    letter-spacing:0;
}

.ai-kpi-card p{
    margin:8px 0 16px;
    color:#8a99ad;
}

.ai-spark{
    display:flex;
    align-items:end;
    gap:7px;
    height:44px;
}

.ai-spark i{
    flex:1;
    min-width:8px;
    border-radius:999px 999px 4px 4px;
    background:linear-gradient(180deg,#00d2ff,#2563eb);
    box-shadow:0 0 18px rgba(0,210,255,.22);
}

.ai-grid{
    display:grid;
    grid-template-columns:minmax(0,1.55fr) minmax(320px,.75fr);
    gap:16px;
    margin-bottom:16px;
}

.ai-insights{
    padding:22px;
    position:relative;
    border-color:rgba(0,210,255,.42);
    box-shadow:0 0 0 1px rgba(0,210,255,.08),0 0 44px rgba(0,210,255,.08),0 22px 60px rgba(0,0,0,.22);
}

.ai-card{
    padding:22px;
}

.ai-section-head h2,
.ai-placeholder h2,
.ai-chat-panel h2{
    margin:0;
    color:#fff;
    font-size:1.2rem;
    font-weight:800;
    letter-spacing:0;
}

.ai-insight-list{
    display:grid;
    gap:12px;
    margin-top:18px;
}

.ai-insight-row{
    display:grid;
    grid-template-columns:auto 54px 1fr;
    gap:14px;
    align-items:center;
    padding:14px;
    border-radius:16px;
    background:rgba(255,255,255,.035);
    border:1px solid rgba(35,45,63,.82);
}

.ai-insight-row b{
    color:#fff;
    font-size:1.35rem;
}

.ai-insight-row p{
    margin:0;
    color:#8a99ad;
}

.ai-status{
    display:inline-flex;
    align-items:center;
    width:max-content;
    min-height:28px;
    padding:0 10px;
    border-radius:999px;
    font-size:.76rem;
    font-weight:800;
    border:1px solid transparent;
}

.ai-status.ok{color:#5cf2ac;background:rgba(16,185,129,.12);border-color:rgba(16,185,129,.24);}
.ai-status.warn{color:#f6c356;background:rgba(245,158,11,.12);border-color:rgba(245,158,11,.24);}
.ai-status.ai{color:#00d2ff;background:rgba(0,210,255,.12);border-color:rgba(0,210,255,.26);}
.ai-status.bad{color:#fb7185;background:rgba(244,63,94,.12);border-color:rgba(244,63,94,.24);}
.ai-status.neutral{color:#cbd5e1;background:rgba(148,163,184,.12);border-color:rgba(148,163,184,.2);}

.ai-diagnosis-list{
    display:grid;
    gap:12px;
    margin-top:18px;
}

.ai-diagnosis-list div{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    padding:13px 0;
    border-bottom:1px solid #232d3f;
    color:#8a99ad;
}

.ai-diagnosis-list b{
    color:#fff;
}

.ai-workspace{
    padding:22px;
}

.ai-tabs{
    display:flex;
    gap:8px;
    flex-wrap:wrap;
    margin-bottom:20px;
}

.ai-tabs button{
    border:1px solid #232d3f;
    border-radius:999px;
    padding:10px 14px;
    background:rgba(255,255,255,.04);
    color:#8a99ad;
    font-weight:900;
    transition:background .2s ease,color .2s ease,border-color .2s ease;
}

.ai-tabs button.active,
.ai-tabs button:hover{
    color:#06111f;
    border-color:#00d2ff;
    background:#00d2ff;
}

.ai-tab-panel{
    display:none;
}

.ai-tab-panel.active{
    display:block;
}

.ai-text-link{
    color:#00d2ff;
    text-decoration:none;
    font-weight:900;
}

.ai-table-wrap{
    margin-top:14px;
    overflow:auto;
}

.ai-table{
    width:100%;
    border-collapse:separate;
    border-spacing:0 8px;
}

.ai-table th{
    padding:10px 14px;
    color:#667085;
    font-size:.78rem;
    text-transform:uppercase;
    letter-spacing:.06em;
}

.ai-table td{
    padding:15px 14px;
    color:#dbe7f7;
    background:rgba(255,255,255,.035);
    border-top:1px solid transparent;
    border-bottom:1px solid transparent;
}

.ai-table tr:hover td{
    background:rgba(0,210,255,.055);
    border-color:rgba(0,210,255,.12);
}

.ai-table td:first-child{
    border-radius:14px 0 0 14px;
}

.ai-table td:last-child{
    border-radius:0 14px 14px 0;
}

.ai-consult{
    display:grid;
    grid-template-columns:minmax(0,1fr) 360px;
    gap:16px;
}

.ai-log-row{
    padding:15px;
    border-radius:16px;
    background:rgba(255,255,255,.035);
    border:1px solid #232d3f;
    margin-top:10px;
}

.ai-log-row b{
    color:#fff;
}

.ai-log-row p,
.ai-empty,
.ai-placeholder p{
    margin:6px 0 0;
    color:#8a99ad;
}

.ai-chat-panel{
    min-height:360px;
    padding:18px;
    border-radius:16px;
    background:linear-gradient(180deg,rgba(0,210,255,.11),rgba(22,27,38,.92));
    border:1px solid rgba(0,210,255,.32);
    box-shadow:0 0 44px rgba(0,210,255,.08);
}

.ai-chat-bubble{
    margin-top:14px;
    padding:13px;
    border-radius:16px;
    color:#dbe7f7;
    background:rgba(255,255,255,.055);
    border:1px solid #232d3f;
}

.ai-chat-bubble.user{
    color:#06111f;
    background:#00d2ff;
}

.ai-chat-panel button{
    width:100%;
    margin-top:18px;
}

.ai-placeholder{
    padding:28px;
    border-radius:16px;
    background:rgba(255,255,255,.035);
    border:1px solid #232d3f;
}

.ai-placeholder a{
    display:inline-flex;
    margin-top:16px;
}

@media(max-width:1200px){
    .ai-kpis{grid-template-columns:repeat(2,minmax(0,1fr));}
    .ai-grid,.ai-consult{grid-template-columns:1fr;}
}

@media(max-width:860px){
    body:has(.ai-admin-shell){overflow:auto;}
    .ai-admin-shell{grid-template-columns:1fr;}
    .ai-side{
        position:relative;
        height:auto;
        border-right:0;
        border-bottom:1px solid #232d3f;
    }
    .ai-nav{grid-template-columns:repeat(2,minmax(0,1fr));}
    .ai-main{height:auto;padding:20px;}
    .ai-top{display:grid;}
}

@media(max-width:620px){
    .ai-kpis{grid-template-columns:1fr;}
    .ai-nav{grid-template-columns:1fr;}
    .ai-insight-row{grid-template-columns:1fr;}
    .ai-table{min-width:760px;}
}

:root{
    --admin-bg:#f5f7fb;
    --admin-surface:#ffffff;
    --admin-surface-soft:#f8fafc;
    --admin-line:#e2e8f0;
    --admin-line-strong:#cbd5e1;
    --admin-text:#172033;
    --admin-muted:#64748b;
    --admin-blue:#2563eb;
    --admin-blue-soft:#eff6ff;
    --admin-green:#16a34a;
    --admin-amber:#d97706;
    --admin-red:#dc2626;
    --admin-radius:14px;
    --admin-shadow:0 14px 34px rgba(15,23,42,.07);
}

body:has(.admin-os-sidebar){
    background:var(--admin-bg) !important;
    color:var(--admin-text) !important;
    overflow:auto !important;
}

body:has(.admin-os-sidebar) > .app-topbar{
    display:flex !important;
}

body:has(.admin-os-sidebar) .layout,
body:has(.admin-os-sidebar) .ai-admin-shell{
    min-height:calc(100vh - 96px) !important;
    gap:16px !important;
    padding:16px !important;
    background:var(--admin-bg) !important;
    color:var(--admin-text) !important;
}

body:has(.admin-os-sidebar) .content,
body:has(.admin-os-sidebar) .ai-main{
    height:auto !important;
    padding:6px 6px 40px !important;
    color:var(--admin-text) !important;
}

body:has(.admin-os-sidebar) h1,
body:has(.admin-os-sidebar) h2,
body:has(.admin-os-sidebar) h3,
body:has(.admin-os-sidebar) h4,
body:has(.admin-os-sidebar) h5,
body:has(.admin-os-sidebar) strong,
body:has(.admin-os-sidebar) b{
    color:var(--admin-text) !important;
    letter-spacing:0 !important;
}

body:has(.admin-os-sidebar) p,
body:has(.admin-os-sidebar) small,
body:has(.admin-os-sidebar) .text-muted,
body:has(.admin-os-sidebar) .dashboard-metric-label,
body:has(.admin-os-sidebar) .ai-empty,
body:has(.admin-os-sidebar) .ai-placeholder p,
body:has(.admin-os-sidebar) .ai-card-note{
    color:var(--admin-muted) !important;
}

body:has(.admin-os-sidebar) .app-topbar,
body:has(.admin-os-sidebar) .topbar{
    top:12px !important;
    height:72px !important;
    margin:12px 16px 0 !important;
    padding:0 18px !important;
    border-radius:16px !important;
    background:rgba(255,255,255,.92) !important;
    border:1px solid #dbeafe !important;
    box-shadow:0 6px 18px rgba(35,52,95,.06) !important;
    backdrop-filter:blur(18px) !important;
}

body:has(.admin-os-sidebar) .brand,
body:has(.admin-os-sidebar) .brand-link,
body:has(.admin-os-sidebar) .brand span:last-child{
    color:var(--admin-text) !important;
}

body:has(.admin-os-sidebar) .user-chip,
body:has(.admin-os-sidebar) .logout-btn,
body:has(.admin-os-sidebar) .notif-drawn-bell{
    color:var(--admin-text) !important;
    background:var(--admin-surface-soft) !important;
    border-color:var(--admin-line) !important;
}

body:has(.admin-os-sidebar) .admin-os-sidebar,
body:has(.admin-os-sidebar) .sidebar{
    top:100px !important;
    width:292px !important;
    height:calc(100vh - 116px) !important;
    padding:16px !important;
    border-radius:16px !important;
    background:#fff !important;
    color:var(--admin-text) !important;
    border:1px solid var(--admin-line) !important;
    box-shadow:var(--admin-shadow) !important;
}

.admin-os-brand{
    display:flex !important;
    align-items:center !important;
    gap:10px !important;
    padding:10px 10px 14px !important;
    color:var(--admin-text) !important;
    text-decoration:none !important;
    border-bottom:1px solid var(--admin-line) !important;
    margin-bottom:12px !important;
}

.admin-os-mark{
    width:40px !important;
    height:40px !important;
    border-radius:12px !important;
    display:grid !important;
    place-items:center !important;
    color:#fff !important;
    background:var(--admin-blue) !important;
    box-shadow:none !important;
}

.admin-os-brand small,
.admin-os-user small{
    display:block;
    color:var(--admin-muted) !important;
}

.admin-os-nav{
    display:grid !important;
    gap:16px !important;
}

.admin-os-section{
    display:grid;
    gap:5px;
}

.admin-os-section-title{
    padding:0 10px 4px;
    color:var(--admin-muted);
    font-size:.72rem;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.08em;
}

body:has(.admin-os-sidebar) .admin-os-nav a,
body:has(.admin-os-sidebar) .app-sidebar a,
body:has(.admin-os-sidebar) .sidebar a{
    min-height:40px !important;
    padding:10px 11px !important;
    border-radius:12px !important;
    color:#334155 !important;
    background:transparent !important;
    border:1px solid transparent !important;
    box-shadow:none !important;
    transform:none !important;
}

body:has(.admin-os-sidebar) .admin-os-nav a span{
    width:26px !important;
    color:var(--admin-muted) !important;
    font-size:.78rem !important;
    font-weight:700 !important;
}

body:has(.admin-os-sidebar) .admin-os-nav a:hover,
body:has(.admin-os-sidebar) .admin-os-nav a.active{
    color:var(--admin-blue) !important;
    background:var(--admin-blue-soft) !important;
    border-color:#bfdbfe !important;
}

body:has(.admin-os-sidebar) .admin-os-user{
    color:var(--admin-text) !important;
    box-shadow:none !important;
}

body:has(.admin-os-sidebar) .admin-os-avatar{
    color:#fff !important;
    background:var(--admin-blue) !important;
}

body:has(.admin-os-sidebar) .hero,
body:has(.admin-os-sidebar) .admin-hero-banner,
body:has(.admin-os-sidebar) .client-hero-banner{
    color:var(--admin-text) !important;
    background:linear-gradient(135deg,#ffffff,#eef6ff) !important;
    border:1px solid var(--admin-line) !important;
    border-radius:18px !important;
    box-shadow:var(--admin-shadow) !important;
}

body:has(.admin-os-sidebar) .hero::before,
body:has(.admin-os-sidebar) .hero::after{
    display:none !important;
}

body:has(.admin-os-sidebar) .hero h1,
body:has(.admin-os-sidebar) .hero h2,
body:has(.admin-os-sidebar) .hero p{
    color:inherit !important;
}

body:has(.admin-os-sidebar) .stat-card,
body:has(.admin-os-sidebar) .dashboard-metric-card,
body:has(.admin-os-sidebar) .soft-card,
body:has(.admin-os-sidebar) .table-card,
body:has(.admin-os-sidebar) .report-card,
body:has(.admin-os-sidebar) .chart-card,
body:has(.admin-os-sidebar) .analytics-card,
body:has(.admin-os-sidebar) .appointment-request-card,
body:has(.admin-os-sidebar) .friendly-appointment-card,
body:has(.admin-os-sidebar) .admin-appointment-card,
body:has(.admin-os-sidebar) .qr-card,
body:has(.admin-os-sidebar) .empty-state,
body:has(.admin-os-sidebar) .ai-kpi-card,
body:has(.admin-os-sidebar) .ai-card,
body:has(.admin-os-sidebar) .ai-insights,
body:has(.admin-os-sidebar) .ai-workspace,
body:has(.admin-os-sidebar) .ai-placeholder,
body:has(.admin-os-sidebar) .ai-log-row,
body:has(.admin-os-sidebar) .ai-chat-panel,
body:has(.admin-os-sidebar) .appt-monitor,
body:has(.admin-os-sidebar) .pet-admin-form-card,
body:has(.admin-os-sidebar) .pet-admin-list-card,
body:has(.admin-os-sidebar) .user-admin-form-card,
body:has(.admin-os-sidebar) .user-admin-list-card{
    color:var(--admin-text) !important;
    background:var(--admin-surface) !important;
    border:1px solid var(--admin-line) !important;
    border-radius:var(--admin-radius) !important;
    box-shadow:var(--admin-shadow) !important;
    backdrop-filter:none !important;
}

body:has(.admin-os-sidebar) .stat-card:hover,
body:has(.admin-os-sidebar) .dashboard-metric-card:hover,
body:has(.admin-os-sidebar) .soft-card:hover,
body:has(.admin-os-sidebar) .table-card:hover,
body:has(.admin-os-sidebar) .report-card:hover,
body:has(.admin-os-sidebar) .ai-kpi-card:hover,
body:has(.admin-os-sidebar) .ai-card:hover,
body:has(.admin-os-sidebar) .ai-insights:hover,
body:has(.admin-os-sidebar) .ai-workspace:hover{
    transform:none !important;
    border-color:var(--admin-line-strong) !important;
    box-shadow:var(--admin-shadow) !important;
}

body:has(.admin-os-sidebar) .ai-kpis{
    gap:14px !important;
}

body:has(.admin-os-sidebar) .ai-kpi-card{
    min-height:148px !important;
    padding:20px !important;
}

body:has(.admin-os-sidebar) .ai-card-head b,
body:has(.admin-os-sidebar) .ai-live-dot,
body:has(.admin-os-sidebar) .diagnosis-period-badge,
body:has(.admin-os-sidebar) .download-pill,
body:has(.admin-os-sidebar) .diagnosis-filter-pill,
body:has(.admin-os-sidebar) .quick-chip,
body:has(.admin-os-sidebar) .filter-chip,
body:has(.admin-os-sidebar) .appt-filter,
body:has(.admin-os-sidebar) .admin-filter-pill{
    color:var(--admin-blue) !important;
    background:var(--admin-blue-soft) !important;
    border:1px solid #bfdbfe !important;
    border-radius:999px !important;
    box-shadow:none !important;
}

