/* Client record: separate profile edits from account access changes. */
#clientEditDialog [hidden]{display:none!important}
#clientEditDialog .client-account-actions{display:flex!important;flex-wrap:wrap!important;justify-content:flex-end!important;gap:10px!important}
#clientEditDialog .client-account-actions button{width:auto!important;min-width:120px!important}
#clientEditDialog .client-account-management{grid-column:1/-1!important;min-width:0!important;border:1px solid #dce5ef!important;border-radius:12px!important;background:#f8fafc!important;padding:12px 14px!important;margin-top:6px!important}
#clientEditDialog .client-account-management summary{cursor:pointer!important;color:#294763!important;font-weight:600!important;font-size:.88rem!important}
#clientEditDialog .client-account-management summary span{font-weight:400!important;color:#687c90!important;font-size:.76rem!important;margin-left:8px!important}
#clientEditDialog .client-account-management p{color:#52677f!important;font-size:.8rem!important;line-height:1.5!important;margin:12px 0!important}
#clientEditDialog .client-account-management small{display:block!important;color:#687c90!important;font-size:.73rem!important;margin-top:10px!important}
#clientEditDialog .client-account-management-buttons{display:flex!important;flex-wrap:wrap!important;gap:8px!important}
#clientEditDialog .client-account-management-buttons button,#clientEditDialog .client-photo-upload button{width:auto!important;min-height:36px!important;padding:8px 12px!important;font-size:.78rem!important;border-radius:9px!important}
#clientEditDialog .client-photo-upload button{justify-self:start!important}
@media(max-width:520px){
 #clientEditDialog .client-account-management summary span{display:block!important;margin:4px 0 0!important}
 #clientEditDialog .client-account-management-buttons button{flex:1 1 150px!important}
 #clientEditDialog .client-account-actions button{flex:1!important}
}
